    }

    pub async fn read_resource(&self, uri: &str) -> Option<String> {
        match uri {
            "docs://system-prompt" => Some(self.generate_system_prompt().await),
            "docs://architecture" => Some(ARCHITECTURE_DOC.to_string()),
            blob if blob.starts_with("blob://") => {
