#[cfg(test)]
mod tests {
    use super::*;
    use axum::extract::ConnectInfo;
    use axum::http::{HeaderMap, HeaderValue};
    use tower::ServiceExt;

    #[tokio::test]
    async fn local_and_missing_peers_do_not_bypass_credentials() {
        for peer in [None, Some("127.0.0.1:4567"), Some("[::1]:4567")] {
            let validator: Arc<dyn AuthValidator> = Arc::new(EnvAllowListValidator::from_env());
            let app = Router::new()
                .route("/ws", get(|| async { "must not run" }))
                .layer(middleware::from_fn_with_state(
                    validator,
                    wireguard_auth_middleware,
                ));
            let mut request = axum::http::Request::builder()
                .uri("/ws")
                .header("host", "localhost")
                .header("origin", "http://localhost")
                .body(axum::body::Body::empty())
                .unwrap();
            if let Some(peer) = peer {
                request
                    .extensions_mut()
                    .insert(ConnectInfo::<SocketAddr>(peer.parse().unwrap()));
            }
            assert_eq!(
                app.oneshot(request).await.unwrap().status(),
                StatusCode::UNAUTHORIZED
            );
        }
    }

    #[tokio::test]
    async fn identity_shaped_headers_do_not_bypass_non_loopback_auth() {
        let validator: Arc<dyn AuthValidator> =
            Arc::new(EnvAllowListValidator::new(Vec::<String>::new()));
        let app = Router::new().route("/mcp", post(|| async { "ok" })).layer(
            middleware::from_fn_with_state(validator, wireguard_auth_middleware),
        );
        let mut request = axum::http::Request::builder()
            .method("POST")
            .uri("/mcp")
            .header("x-ghostbridge-footprint", "asserted")
            .header("x-ghostbridge-trace-id", "asserted")
            .body(axum::body::Body::empty())
            .unwrap();
        request.extensions_mut().insert(ConnectInfo::<SocketAddr>(
            "192.0.2.10:4567".parse().unwrap(),
        ));

        let response = app.oneshot(request).await.unwrap();
        assert_eq!(response.status(), StatusCode::UNAUTHORIZED);
    }

    #[test]
    fn should_extract_bearer_token() {
        let mut headers = HeaderMap::new();
        headers.insert(
            "authorization",
            HeaderValue::from_static("Bearer 123e4567-e89b-12d3-a456-426614174000"),
        );

        assert_eq!(
            extract_bearer_token(&headers),
            Some("123e4567-e89b-12d3-a456-426614174000")
        );
    }

    #[test]
    fn shape_check_accepts_pubkey_and_uuid() {
        assert!(is_wireguard_auth_token_shape(
            "123e4567-e89b-12d3-a456-426614174000"
        ));
        assert!(is_wireguard_auth_token_shape(
            "MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWY="
        ));
        assert!(!is_wireguard_auth_token_shape("ya29.google-oauth-token"));
        assert!(!is_wireguard_auth_token_shape("not-a-wireguard-token"));
    }

    #[tokio::test]
    async fn identifiers_remain_denied_even_if_allowlisted() {
        let v = EnvAllowListValidator::new(vec!["123e4567-e89b-12d3-a456-426614174000"]);
        assert!(!v.validate("123e4567-e89b-12d3-a456-426614174000").await);
        assert!(!v.validate("00000000-0000-0000-0000-000000000000").await);
        assert!(!v.validate("garbage").await);
        // wrong shape is rejected even though it would be exactly equal to no
        // entry anyway
        assert!(!v.validate("not-a-wireguard-token").await);
    }

    #[tokio::test]
    async fn validator_with_no_entries_rejects_everything() {
        let v = EnvAllowListValidator::new(Vec::<String>::new());
        assert!(!v.validate("123e4567-e89b-12d3-a456-426614174000").await);
        assert!(
            !v.validate("MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWY=")
                .await
        );
    }
}

