317:    async fn subscribe(
318:        &self,
319:        request: Request<SubscribeRequest>,
320:    ) -> Result<Response<Self::SubscribeStream>, Status> {
321:        self.ensure_supported_mode()?;
322:        let req = request.into_inner();
323:        let _session_id = req.session_id.unwrap_or_else(|| Uuid::new_v4().to_string());
324:        let event_filter: Vec<String> = req.event_types;
325:        let (tx, rx) = mpsc::channel(32);
326:        let mut event_rx = self.event_tx.subscribe();
327:
328:        tokio::spawn(async move {
329:            let mut sequence = 0u32;
330:            let mut heartbeat = tokio::time::interval(Duration::from_secs(30));
331:
332:            loop {
333:                tokio::select! {
334:                    // Forward real events from the broadcast channel
335:                    recv_result = event_rx.recv() => {
336:                        match recv_result {
337:                            Ok(mut event) => {
338:                                // Filter by requested event_types (empty = accept all)
339:                                if !event_filter.is_empty()
340:                                    && !event_filter.iter().any(|t| t == &event.event_type)
341:                                {
342:                                    continue;
343:                                }
344:                                event.sequence = sequence;
345:                                sequence += 1;
346:                                if tx.send(Ok(event)).await.is_err() {
347:                                    break; // client disconnected
348:                                }
349:                            }
350:                            Err(broadcast::error::RecvError::Lagged(n)) => {
351:                                warn!("Subscription lagged, dropped {} events", n);
352:                                // Continue receiving, don't kill the stream
353:                            }
354:                            Err(broadcast::error::RecvError::Closed) => {
355:                                break; // sender side dropped
356:                            }
357:                        }
358:                    }
359:                    // Periodic heartbeat so the client knows the stream is alive
360:                    _ = heartbeat.tick() => {
361:                        let ping = McpEvent {
362:                            event_type: "ping".to_string(),
363:                            data_json: String::new(),
364:                            timestamp: chrono::Utc::now().timestamp(),
365:                            sequence,
366:                        };
367:                        sequence += 1;
368:                        if tx.send(Ok(ping)).await.is_err() {
369:                            break;
370:                        }
371:                    }
372:                }
373:            }
374:        });
375:
376:        Ok(Response::new(
377:            Box::pin(ReceiverStream::new(rx)) as Self::SubscribeStream
378:        ))
379:    }
