fn convert_json_schema_to_tool_schema(schema: &Value) -> ToolSchema {
    let mut parameters = Vec::new();
    if let Some(props) = schema.get("properties").and_then(|v| v.as_object()) {
        for (name, prop) in props {
            let p_type = prop
                .get("type")
                .and_then(|v| v.as_str())
                .unwrap_or("string");
            let param_type = match p_type {
                "string" => ParameterType::String,
                "integer" => ParameterType::Integer,
                "number" => ParameterType::Number,
                "boolean" => ParameterType::Boolean,
                "array" => ParameterType::Array,
                "object" => ParameterType::Object,
                _ => ParameterType::String,
            };
            parameters.push(ToolParameter {
                name: name.to_string(),
                r#type: param_type as i32,
                description: prop
                    .get("description")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string(),
                default_value: None,
                enum_values: vec![],
            });
        }
    }
    ToolSchema {
        parameters,
        required: vec![],
    }
}

#[cfg(test)]
mod mode_tests {
    use super::*;

    #[tokio::test]
    async fn blob_schema_mode_never_claims_registry_is_sealed_catalog() {
        let service = McpGrpcService::new(ServerMode::BlobSchema);
        let status = service
            .list_tools(Request::new(ListToolsRequest::default()))
            .await
            .unwrap_err();
        assert_eq!(status.code(), tonic::Code::Unimplemented);
        assert!(
            service
                .call_tool(Request::new(CallToolRequest::default()))
                .await
                .is_err()
        );
    }
}

