1://! Build script for op-mcp
2://!
3://! Compiles proto files when the grpc feature is enabled.
4:
5:fn main() -> Result<(), Box<dyn std::error::Error>> {
6:    #[cfg(feature = "grpc")]
7:    {
8:        let proto_file = "proto/mcp.proto";
9:
